# 30_tables.R: summary tables for the redesigned Figure 6 (no refitting). Medians and central 95% intervals across the 30 random splits where the matched interval is supported by the training sites; descriptive, not significance tests.
suppressMessages({library(dplyr); library(tidyr)}); T <- "revision_fig6/tables/"; q <- function(x, p) if (sum(is.finite(x)) < 3) NA_real_ else unname(quantile(x, p, type = 7, na.rm = TRUE))
S <- read.csv(paste0(T, "fig6_splits_contrasts.csv")); H <- read.csv(paste0(T, "fig6_splits_heldout.csv"))
av <- S |> group_by(pool, group, order) |> summarise(n_splits = n_distinct(split), n_splits_supported = n_distinct(split[available]), prop_supported = n_splits_supported / n_splits, .groups = "drop"); write.csv(av, paste0(T, "fig6_summary_split_support.csv"), row.names = FALSE)
sm <- function(d, grp) d |> group_by(across(all_of(grp))) |> summarise(n_splits = n(), dT_median = median(dT_pp), dT_q025 = q(dT_pp, .025), dT_q975 = q(dT_pp, .975), dO_median = median(dO_pp), dO_q025 = q(dO_pp, .025), dO_q975 = q(dO_pp, .975), dH_median = median(dH_pp), dH_q025 = q(dH_pp, .025), dH_q975 = q(dH_pp, .975), compensated_median = median(compensated_pp), compensated_q025 = q(compensated_pp, .025), compensated_q975 = q(compensated_pp, .975),
  gross_median = median(gross_pp), prop_opposing_signs = mean(opposing), prop_O_positive = mean(dO_pp > 0), prop_H_negative = mean(dH_pp < 0), .groups = "drop")
SA <- S |> filter(available, contrast == "A_spread") |> sm(c("pool", "group", "order", "model", "position")); write.csv(SA, paste0(T, "fig6_summary_splits_contrast_A.csv"), row.names = FALSE)
SB <- S |> filter(available, contrast == "B_position_low_to_high") |> sm(c("pool", "group", "order", "model")); write.csv(SB, paste0(T, "fig6_summary_splits_contrast_B.csv"), row.names = FALSE)
Hw <- H |> select(pool, split, group, order, model, component, D2) |> pivot_wider(names_from = model, values_from = D2) |> mutate(gain = additive - spread_only); write.csv(Hw |> group_by(pool, group, order, component) |> summarise(n_splits = n(), D2_spread_only_median = median(spread_only), D2_additive_median = median(additive), gain_median = median(gain), gain_q025 = q(gain, .025), gain_q975 = q(gain, .975), n_gain_positive = sum(gain > 0), .groups = "drop"), paste0(T, "fig6_summary_heldout_D2.csv"), row.names = FALSE)
# all-site compensation for contrast B and decomposition
B <- read.csv(paste0(T, "fig6_contrast_B_position.csv")); source_comp <- function(dT, dO, dH, thr = .05) { gross <- abs(dO) + abs(dH); comp <- (gross - abs(dT)) / 2; data.frame(gross_pp = gross, net_total_pp = abs(dT), compensated_pp = comp, opposing = (dO * dH < 0) & pmin(abs(dO), abs(dH)) >= thr, fraction_compensated = ifelse(gross >= 1, comp / gross, NA_real_)) }
Bc <- cbind(B, source_comp(B$dT_pp, B$dO_pp, B$dH_pp)); write.csv(Bc, paste0(T, "fig6_contrast_B_with_compensation.csv"), row.names = FALSE)
dec <- B |> filter(position_from == "Low", position_to == "High") |> select(pool, group, order, model, spread, dT_pp, dO_pp, dH_pp, spline_slope_dT, explicit_position_dT, spline_slope_dO, explicit_position_dO, spline_slope_dH, explicit_position_dH, dEtaT, dEtaT_spline_slope, dEtaT_explicit_position, dEtaS, dEtaS_spline_slope, dEtaS_explicit_position); write.csv(dec, paste0(T, "fig6_position_decomposition.csv"), row.names = FALSE)
# model comparison of conditional contrasts (all-site): what the explicit position terms add
A <- read.csv(paste0(T, "fig6_contrast_A_spread.csv")); cmp <- A |> select(pool, group, order, model, position, dT_pp, dO_pp, dH_pp, compensated_pp) |> pivot_wider(names_from = model, values_from = c(dT_pp, dO_pp, dH_pp, compensated_pp)) |> mutate(dT_diff_additive_minus_spreadonly = dT_pp_additive - dT_pp_spread_only, dO_diff = dO_pp_additive - dO_pp_spread_only, dH_diff = dH_pp_additive - dH_pp_spread_only); write.csv(cmp, paste0(T, "fig6_contrast_A_model_comparison.csv"), row.names = FALSE)
options(width = 220, digits = 3); print(av); print(as.data.frame(Hw |> filter(pool == "shared") |> group_by(group, order, component) |> summarise(gain = median(gain), npos = sum(gain > 0), n = n(), .groups = "drop")))
